import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Learning Roadmap","description":"From Agent basics to payments and AgentPay: Understanding how autonomous AI agents safely spend money.","frontmatter":{"title":"Learning Roadmap","description":"From Agent basics to payments and AgentPay: Understanding how autonomous AI agents safely spend money."},"headers":[],"relativePath":"learn/index.md","filePath":"learn/index.md","lastUpdated":1792595354000}'),i={name:"learn/index.md"};function o(s,e,l,d,p,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="learning-roadmap" tabindex="-1">Learning Roadmap <a class="header-anchor" href="#learning-roadmap" aria-label="Permalink to &quot;Learning Roadmap&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay is currently experimental and <strong>has not undergone an independent security audit. Do not use with production funds.</strong> Testing on testnets with test tokens is strongly recommended.</p></div><p>Agents are evolving from &quot;answering questions&quot; to &quot;executing tasks&quot;: calling paid APIs, purchasing data, renting compute, and even hiring other agents. When agents begin to spend money, a fundamental question emerges:</p><blockquote><p><strong>Without human sign-off on every transaction, under what conditions is an agent authorized to spend money?</strong></p></blockquote><p>This knowledge base explains the background of the problem and how AgentPay addresses it. No prior blockchain or payment expertise is required.</p><h2 id="agentpay-in-a-nutshell" tabindex="-1">AgentPay in a Nutshell <a class="header-anchor" href="#agentpay-in-a-nutshell" aria-label="Permalink to &quot;AgentPay in a Nutshell&quot;">​</a></h2><p><strong>LLMs can propose payments, but must never approve payments.</strong></p><p>AgentPay is an independent control layer placed between agents and real funds. Per-transaction limits, rolling budgets, payee whitelists, circuit breakers, failure recovery, and audit trails are all enforced by deterministic code, never left to model discretion.</p><p>Division of responsibility with the x402 protocol:</p><table tabindex="0"><thead><tr><th></th><th>Question Answered</th></tr></thead><tbody><tr><td><strong>x402</strong></td><td>How to pay?</td></tr><tr><td><strong>AgentPay</strong></td><td>Should it be paid? How much? What happens if it fails?</td></tr></tbody></table><h2 id="where-should-i-start" tabindex="-1">Where Should I Start? <a class="header-anchor" href="#where-should-i-start" aria-label="Permalink to &quot;Where Should I Start?&quot;">​</a></h2><h3 id="🚀-want-to-see-results-first-10-minute-experience" tabindex="-1">🚀 Want to see results first: 10-Minute Experience <a class="header-anchor" href="#🚀-want-to-see-results-first-10-minute-experience" aria-label="Permalink to &quot;🚀 Want to see results first: 10-Minute Experience&quot;">​</a></h3><p>Walk through three scenarios in one script: <strong>Normal payment success → Over-budget rejection → Runaway loop tripped by circuit breaker</strong>.</p><p>→ <a href="./05-hands-on/ten-minute-demo">10-Minute Demo</a></p><h3 id="choose-your-learning-path-by-role" tabindex="-1">Choose Your Learning Path by Role <a class="header-anchor" href="#choose-your-learning-path-by-role" aria-label="Permalink to &quot;Choose Your Learning Path by Role&quot;">​</a></h3><h4 id="i-am-an-agent-developer-buyer" tabindex="-1">I am an Agent Developer (Buyer) <a class="header-anchor" href="#i-am-an-agent-developer-buyer" aria-label="Permalink to &quot;I am an Agent Developer (Buyer)&quot;">​</a></h4><p>I want my agent to safely call paid APIs without draining funds.</p><ol><li><a href="./01-agent-basics/agent-failure-modes">Common Agent Failure Modes</a></li><li><a href="./04-agentpay-concepts/financial-firewall">Why We Need a Financial Firewall</a></li><li><a href="./04-agentpay-concepts/budget-reservation">Budget Reservation: Why &quot;Check Then Pay&quot; Fails</a></li><li><a href="./04-agentpay-concepts/timeout-is-not-failure">Timeout Is Not Failure</a></li><li><a href="./05-hands-on/ten-minute-demo">10-Minute Demo</a></li></ol><h4 id="i-am-an-api-provider-seller" tabindex="-1">I am an API Provider (Seller) <a class="header-anchor" href="#i-am-an-api-provider-seller" aria-label="Permalink to &quot;I am an API Provider (Seller)&quot;">​</a></h4><p>I want to monetize my API into a pay-per-request endpoint.</p><ol><li><a href="./02-agent-payments/http-402-and-x402">HTTP 402 &amp; x402</a></li><li><a href="./04-agentpay-concepts/payment-lifecycle">Complete Payment Lifecycle</a></li><li><a href="./05-hands-on/first-paid-route">Configure Your First Paid Route in the Console</a></li><li><a href="./05-hands-on/draft-publish-rollback">Draft, Publish &amp; Rollback</a></li></ol><h4 id="i-am-an-enterprise-administrator" tabindex="-1">I am an Enterprise Administrator <a class="header-anchor" href="#i-am-an-enterprise-administrator" aria-label="Permalink to &quot;I am an Enterprise Administrator&quot;">​</a></h4><p>I manage multiple agents and am accountable for all outgoing expenditures.</p><ol><li><a href="./03-infra-map/agent-stack">Agent Infrastructure Landscape</a></li><li><a href="./04-agentpay-concepts/multi-tenant">Tenants, Projects, Agents &amp; API Keys</a></li><li><a href="./04-agentpay-concepts/dual-rail">Dual-Rail Architecture: Virtual Wallets vs On-Chain</a></li><li><a href="./04-agentpay-concepts/agent-identity">Agent Identity: Observation vs Self-Reporting</a></li><li><a href="./05-hands-on/audit-timeline">Troubleshooting with Audit Timelines</a></li></ol><h2 id="complete-table-of-contents" tabindex="-1">Complete Table of Contents <a class="header-anchor" href="#complete-table-of-contents" aria-label="Permalink to &quot;Complete Table of Contents&quot;">​</a></h2><p>Organized from broad to specific: first universal agent and payment knowledge, then where AgentPay fits in the infrastructure stack, followed by core architectural concepts and hands-on tutorials.</p><h3 id="chapter-1-agent-development-basics" tabindex="-1">Chapter 1: Agent Development Basics <a class="header-anchor" href="#chapter-1-agent-development-basics" aria-label="Permalink to &quot;Chapter 1: Agent Development Basics&quot;">​</a></h3><p>Universal knowledge independent of AgentPay, explaining why agents require financial boundaries.</p><p><a href="./01-agent-basics/what-is-an-agent">What is an Agent</a> · <a href="./01-agent-basics/tool-calling">Tool Calling</a> · <a href="./01-agent-basics/mcp">MCP Standard</a> · <a href="./01-agent-basics/agent-frameworks">Agent Frameworks</a> · <a href="./01-agent-basics/agent-failure-modes">Failure Modes</a> · <a href="./01-agent-basics/autonomy-levels">Autonomy Levels</a></p><h3 id="chapter-2-agent-payments" tabindex="-1">Chapter 2: Agent Payments <a class="header-anchor" href="#chapter-2-agent-payments" aria-label="Permalink to &quot;Chapter 2: Agent Payments&quot;">​</a></h3><p>Why agents need to spend money, limitations of current payment methods, and what x402 and stablecoins solve.</p><p><a href="./02-agent-payments/">Chapter index</a> · <a href="./02-agent-payments/why-agents-pay">Why Agents Need to Pay</a> · <a href="./02-agent-payments/payment-options">Payment Options Compared</a> · <a href="./02-agent-payments/http-402-and-x402">HTTP 402 &amp; x402</a> · <a href="./02-agent-payments/stablecoins-and-usdc">Stablecoins &amp; USDC</a> · <a href="./02-agent-payments/gasless-eip-3009">Gasless Auth (EIP-3009)</a> · <a href="./02-agent-payments/micropayment-economics">Micropayment Economics</a> · <a href="./02-agent-payments/trust-problems">Five Trust Problems</a> · <a href="./02-agent-payments/agent-payment-challenges">Agent Payment Challenges</a> · <a href="./02-agent-payments/agent-payment-flow">Payment Flow</a> · <a href="./02-agent-payments/payment-state-and-idempotency">Payment State &amp; Idempotency</a> · <a href="./02-agent-payments/spending-policy">Spending Policy</a> · <a href="./02-agent-payments/ecosystem-landscape">Ecosystem Landscape</a></p><h3 id="chapter-3-infrastructure-map" tabindex="-1">Chapter 3: Infrastructure Map <a class="header-anchor" href="#chapter-3-infrastructure-map" aria-label="Permalink to &quot;Chapter 3: Infrastructure Map&quot;">​</a></h3><p>Connecting earlier concepts to understand where AgentPay sits in the agent infrastructure stack and what it deliberately does not do.</p><p><a href="./03-infra-map/agent-stack">Agent Stack Layers</a> · <a href="./03-infra-map/where-agentpay-fits">Where AgentPay Fits</a> · <a href="./03-infra-map/agentpay-vs-x402">AgentPay vs x402</a></p><h3 id="chapter-4-agentpay-core-concepts" tabindex="-1">Chapter 4: AgentPay Core Concepts <a class="header-anchor" href="#chapter-4-agentpay-core-concepts" aria-label="Permalink to &quot;Chapter 4: AgentPay Core Concepts&quot;">​</a></h3><p>The &quot;why&quot; behind the design, with each article starting from a real failure scenario.</p><p><a href="./04-agentpay-concepts/financial-firewall">Financial Firewall</a> · <a href="./04-agentpay-concepts/payment-lifecycle">Payment Lifecycle</a> · <a href="./04-agentpay-concepts/timeout-is-not-failure">Timeout Is Not Failure</a> · <a href="./04-agentpay-concepts/three-state-model">Three-State Model</a> · <a href="./04-agentpay-concepts/budget-reservation">Budget Reservation</a> · <a href="./04-agentpay-concepts/dual-rail">Dual-Rail Architecture</a> · <a href="./04-agentpay-concepts/agent-identity">Agent Identity</a> · <a href="./04-agentpay-concepts/idempotency">Idempotency &amp; Free Replays</a> · <a href="./04-agentpay-concepts/multi-tenant">Multi-Tenant Model</a> · <a href="./04-agentpay-concepts/threat-model-lite">Threat Model Lite</a></p><h3 id="chapter-5-hands-on-tutorials" tabindex="-1">Chapter 5: Hands-On Tutorials <a class="header-anchor" href="#chapter-5-hands-on-tutorials" aria-label="Permalink to &quot;Chapter 5: Hands-On Tutorials&quot;">​</a></h3><p>Practical guides based on Python SDK, Go Gateway, and Web Management Console.</p><p><a href="./05-hands-on/ten-minute-demo">10-Minute Demo</a> · <a href="./05-hands-on/first-paid-route">First Paid Route</a> · <a href="./05-hands-on/policy-in-action">Policy in Action</a> · <a href="./05-hands-on/read-payment-trace">Read Payment Trace</a> · <a href="./05-hands-on/audit-timeline">Audit Timeline &amp; Kill Switch</a> · <a href="./05-hands-on/draft-publish-rollback">Draft, Publish &amp; Rollback</a></p><h3 id="chapter-6-quick-reference" tabindex="-1">Chapter 6: Quick Reference <a class="header-anchor" href="#chapter-6-quick-reference" aria-label="Permalink to &quot;Chapter 6: Quick Reference&quot;">​</a></h3><p><a href="./06-resources/glossary">Glossary</a> · <a href="./06-resources/id-prefixes">ID Prefixes</a> · <a href="./06-resources/safety-redlines">Safety Redlines</a> · <a href="./06-resources/faq">FAQ</a> · <a href="./06-resources/further-reading">Further Reading</a></p><h2 id="differences-between-learn-guide-and-specs" tabindex="-1">Differences Between Learn, Guide, and Specs <a class="header-anchor" href="#differences-between-learn-guide-and-specs" aria-label="Permalink to &quot;Differences Between Learn, Guide, and Specs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Question Answered</th><th>When to Read</th></tr></thead><tbody><tr><td><strong>Learn</strong> (Here)</td><td>Why is it designed this way?</td><td>Understanding concepts, threat models, and rationale</td></tr><tr><td><strong>Guide</strong></td><td>How do I do it?</td><td>Hands-on deployment, coding, and configuration</td></tr><tr><td><strong>Specs</strong></td><td>What is the exact contract?</td><td>Implementation, protocol integration, or auditing details</td></tr></tbody></table><p>Learn focuses on design concepts without repeating raw specification text. Each concept page links to corresponding Specs for deep dives.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>Amounts are represented in <strong>atomic integer units</strong> (USDC uses 6 decimals: <code>1 USDC = 1_000_000</code>). No floating-point numbers are used.</li><li>Code samples default to the <strong>Python SDK</strong>.</li><li>Sample networks default to <strong>testnets</strong> (such as Arbitrum Sepolia) with test tokens.</li></ul>',48)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
